from fastapi import FastAPI
from pydantic import BaseModel, computed_field, Field
from fastapi.openapi.utils import get_openapi
import json

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float
    secret: str = Field(..., exclude=True)

    @computed_field
    @property
    def total(self) -> float:
        return self.price * 1.2

@app.get("/items", response_model=Item)
def read_item():
    return Item(name="test", price=10.0, secret="shhh")

def test_openapi_computed_fields(separate_input_output_schemas: bool):
    openapi_schema = get_openapi(
        title="Test",
        version="1.0.0",
        routes=app.routes,
        separate_input_output_schemas=separate_input_output_schemas,
    )

    # Find the Item schema
    schemas = openapi_schema.get("components", {}).get("schemas", {})
    item_schema = schemas.get("Item")

    if not item_schema:
        print(f"Item schema not found for separate_input_output_schemas={separate_input_output_schemas}")
        return False, False

    properties = item_schema.get("properties", {})
    print(f"Properties for separate_input_output_schemas={separate_input_output_schemas}: {list(properties.keys())}")

    return "total" in properties, "secret" in properties

if __name__ == "__main__":
    print("Testing with separate_input_output_schemas=True")
    res_true_total, res_true_secret = test_openapi_computed_fields(True)
    print(f"Total: {res_true_total}, Secret: {res_true_secret}")

    print("\nTesting with separate_input_output_schemas=False")
    res_false_total, res_false_secret = test_openapi_computed_fields(False)
    print(f"Total: {res_false_total}, Secret: {res_false_secret}")

    if res_true_total and not res_false_total:
        print("\nBUG REPRODUCED: computed fields are missing when separate_input_output_schemas=False")
        exit(1)
    elif res_true_total and res_false_total:
        print("\nBUG FIXED: computed fields are present in both cases")
        if res_false_secret:
            print("Note: secret field is also present when separate_input_output_schemas=False")
        else:
            print("Note: secret field is missing when separate_input_output_schemas=False (expected if using serialization schema)")
        exit(0)
    else:
        print("\nUnexpected result")
        exit(1)
